    "expect": "",
    "schema": {
      "type": "page",
      "body": {
        "type": "form",
        "title": "表单状态切换",
        "mode": "horizontal",
        "labelWidth": 150,
        "id": "allFormSwitch",
        "data": {
          "isStatic": false
        },
        "body": [
          {
            "type": "input-text",
            "name": "var1",
            "label": "输入框",
            "value": "text"
          },
          {
            "type": "input-color",
            "name": "var2",
            "label": "颜色选择",
            "value": "#F0F"
          },
          {
            "type": "switch",
            "name": "switch",
            "label": "开关",
            "option": "开关说明",
            "value": true
          },
          {
            "type": "button-toolbar",
            "buttons": [
              {
                "type": "button",
                "label": "${isStatic ? '编辑' : '提交'}",
                "level": "primary",
                "onEvent": {
                  "click": {
                    "actions": [
                      {
                        "actionType": "setValue",
                        "componentId": "allFormSwitch",
                        "args": {
                          "value": {
                            "isStatic": "${!isStatic}"
                          }
                        }
                      },
                      {
                        "actionType": "static",
                        "componentId": "allFormSwitch",
                        "expression": "${!isStatic}"
                      },
                      {
                        "actionType": "nonstatic",
                        "componentId": "allFormSwitch",
                        "expression": "${isStatic}"
                      }
                    ]
                  }
                }
              }
            ]
          }
        ],
        "actions": []
      }
    },
    "measure": {
      "type": "tree"
    }
